func compactORSetState(tx *sql.Tx, documentID string) error {
	// A tombstoned tag is dead: it can never become live again (its operation
	// id is taken), so the tag and every tombstone covering it leave the merge
	// untouched. Live tags and their operations stay.
	if _, err := tx.Exec(
		`DELETE FROM crdt_orset_tags
