			if len(payload) == 0 || payload[len(payload)-1] != '\n' {
				c.t.Fatalf("state frame is not newline-terminated: %q", payload)
			}
			line := string(payload[:len(payload)-1])
			if strings.ContainsAny(line, "\r\n") {
