			return state
		case wsOpcodePong:
			continue
		case wsOpcodeClose:
			c.t.Fatalf("unexpected close frame while reading state: code=%d", closeCode(payload))
		default:
			c.t.Fatalf("unexpected opcode %d while reading state", opcode)
