	if got := crdtCounterValue(t, conn.readCRDTState()); got != 3 {
		t.Fatalf("first state = %d, want 3", got)
	}
	if got := crdtCounterValue(t, conn.readCRDTState()); got != 5 {
		t.Fatalf("second state = %d, want 5", got)
	}

